questionvariables.text:
/* Questions */

funcA:rand(["cos","sin"]);

ansListA: [[1, false, sconcat("\\(\\", funcA, "(\\theta \\pm 90)\\)")], [2, false, sconcat("\\(\\", funcA, "(\\theta \\pm 180)\\)")],[3, true, sconcat("\\(-\\", funcA, "(\\theta \\pm 180)\\)")], [4, true, sconcat("\\(\\", funcA, "(\\theta \\pm 360)\\)")], [5, is(funcA="cos"), sconcat("\\(\\", funcA, "(-\\theta)\\)")], [6, is(funcA="sin"), sconcat("\\(\\", funcA, "(180-\\theta)\\)")], [7, is(funcA="sin"), sconcat("\\(-\\", funcA, "(-\\theta)\\)")], [8, is(funcA="cos"), sconcat("\\(-\\", funcA, "(180-\\theta)\\)")], [9, false, sconcat("\\(\\", if funcA="cos" then "sin" else if funcA="sin" then "cos", "(\\theta)\\)")], [10, true, sconcat("\\(\\", if funcA="cos" then "sin" else if funcA="sin" then "cos", "(90-\\theta)\\)")], [11, false, "\\(\\tan(\\theta)\\)"], [12, false, "\\(\\tan(180-\\theta)\\)"]];

funcB:rand(["(180+\\theta)","(180-\\theta)","(-\\theta)"]);

ansListB1: [[" ", false], ["+", is(funcB="(180-\\theta)")], ["-", not(is(funcB="(180-\\theta)"))]];
ansListB2: [[" ", false], ["+", is(funcB="(-\\theta)")], ["-", not(is(funcB="(-\\theta)"))]];
ansListB3: [[" ", false], ["+", is(funcB="(180+\\theta)")], ["-", not(is(funcB="(180+\\theta)"))]];

/* Solutions */

tans1: if funcA="cos" then [3,4,5,8,10] else if funcA="sin" then [3,4,6,7,10];

tans2: if funcB="(180-\\theta)" then "+" else "-";

tans3: if funcB="(-\\theta)" then "+" else "-";

tans45: if funcB="(180+\\theta)" then "+" else "-";

feedbackvariables.text:
/* Node 1: Check correct answer */

/* Node 2: Feedback and worked solution */

noCorr: length(intersection(setify(ans1), setify(tans1)));
marks: max(2*noCorr - length(setify(ans1)), 0);

/* Node 3: Awarding 4 marks */
/* Node 4: Awarding 3 marks */
/* Node 5: Awarding 2 marks */
/* Node 6: Awarding 1 marks */
/* Node 7: Awarding 0 marks */

/* Node 1: Check correct solution */
node1_test: if ans2=tans2 and ans3=tans3 and ans4=tans45 and ans5=tans5 then 1 else 0;

/* Node 2: Worked solution */

/* Node 3: Check sin correct (+1) */
/* Node 4: Check cos correct (+1) */
/* Node 5: Check tan correct (+1) */
node5_test: if ans4=tans45 and ans5=tans45 then 1 else 0;
